import { NextRequest, NextResponse } from 'next/server';

const ASSETS: Record<string, { contentType: string; data: Buffer }> = {
  'gts-og-preview.mp4': {
    contentType: 'video/mp4',
    data: Buffer.from('', 'base64'),
  },
  'gts-og-poster.jpg': {
    contentType: 'image/jpeg',
    data: Buffer.from('', 'base64'),
  },
  'grocery-outreach-banner.jpg': {
    contentType: 'image/jpeg',
    data: Buffer.from('', 'base64'),
  },
};

function serve(req: NextRequest, filename: string, headOnly: boolean): NextResponse {
  const asset = ASSETS[filename];
  if (!asset) {
    return new NextResponse('Not Found', { status: 404 });
  }

  const total = asset.data.byteLength;
  const baseHeaders: Record<string, string> = {
    'Content-Type': asset.contentType,
    'Accept-Ranges': 'bytes',
    'Cache-Control': 'public, max-age=31536000, immutable',
  };

  const range = req.headers.get('range');
  if (range && range.startsWith('bytes=')) {
    const [startStr, endStr] = range.slice(6).split('-');
    const start = startStr ? parseInt(startStr, 10) : 0;
    const end = endStr ? Math.min(parseInt(endStr, 10), total - 1) : total - 1;
    if (!Number.isNaN(start) && !Number.isNaN(end) && start >= 0 && start <= end && start < total) {
      const chunk = asset.data.subarray(start, end + 1);
      return new NextResponse(headOnly ? null : new Uint8Array(chunk), {
        status: 206,
        headers: {
          ...baseHeaders,
          'Content-Range': `bytes ${start}-${end}/${total}`,
          'Content-Length': String(chunk.byteLength),
        },
      });
    }
  }

  return new NextResponse(headOnly ? null : new Uint8Array(asset.data), {
    status: 200,
    headers: {
      ...baseHeaders,
      'Content-Length': String(total),
    },
  });
}

export async function GET(
  req: NextRequest,
  context: { params: Promise<{ filename: string }> }
) {
  const { filename } = await context.params;
  return serve(req, filename, false);
}

export async function HEAD(
  req: NextRequest,
  context: { params: Promise<{ filename: string }> }
) {
  const { filename } = await context.params;
  return serve(req, filename, true);
}
